import React, { useEffect, useState } from "react";
import axios from "axios";
import AlertBox from "./AlertBox";

function AssignmentsStudent() {
  const studentId = localStorage.getItem("user_id");

  const [assignments, setAssignments] = useState([]);
  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [files, setFiles] = useState({});
  const [alert, setAlert] = useState(null);

  useEffect(() => {
    const fetchCourses = async () => {
      try {
        const res = await axios.get("http://127.0.0.1:8000/courses");
        const allCourses = res.data.courses || [];

        const enrollRes = await axios.get(
          `http://127.0.0.1:8000/enrollments/${studentId}`
        );

        const enrolledIds = enrollRes.data.map((e) => e.course_id);
        const myCourses = allCourses.filter((c) => enrolledIds.includes(c.id));
        setCourses(myCourses);
      } catch (err) {
        console.error(err);
      }
    };

    fetchCourses();
  }, [studentId]);

  const loadAssignments = async (subjectCode) => {
   try {
     const res = await axios.get(
      `http://127.0.0.1:8000/assignments/${subjectCode}`
    );
    setAssignments(res.data.assignments || []);
  } catch (err) {
    console.error(err);
  }
};

  const handleSubmit = async (assignmentId) => {
    try {
      const selectedFile = files[assignmentId];

      if (!selectedFile) {
        setAlert({
          message: "Please choose a PDF or image file",
          type: "error"
        });
        return;
      }

      const formData = new FormData();
      formData.append("assignment_id", assignmentId);
      formData.append("student_id", studentId);
      formData.append("file", selectedFile);

      const res = await axios.post(
        "http://127.0.0.1:8000/submit-assignment",
        formData,
        {
          headers: {
            "Content-Type": "multipart/form-data"
          }
        }
      );

      setAlert({
        message: res.data.message,
        type: "success"
      });

      window.dispatchEvent(new Event("plannerUpdated"));
    } catch (err) {
      console.error(err);
      setAlert({
        message: "Submission failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2>Student Assignments</h2>

      <select
        value={selectedCourse}
        onChange={(e) => {
          setSelectedCourse(e.target.value);
          loadAssignments(e.target.value);
        }}
      >
        <option value="">Select Course</option>
        {courses.map((course) => (
          <option key={course.id} value={course.id}>
            {course.title}
          </option>
        ))}
      </select>

      <div style={{ marginTop: "20px" }}>
        {assignments.map((assignment) => (
          <div
            key={assignment.id}
            style={{
              border: "1px solid #ddd",
              padding: "15px",
              borderRadius: "12px",
              marginBottom: "15px"
            }}
          >
            <h3>{assignment.title}</h3>
            <p>{assignment.description}</p>
            <p><strong>Due Date:</strong> {assignment.due_date}</p>

            <input
              type="file"
              accept=".pdf,image/png,image/jpeg,image/jpg"
              onChange={(e) =>
                setFiles({
                  ...files,
                  [assignment.id]: e.target.files[0]
                })
              }
              style={{ marginTop: "10px" }}
            />

            <button
              onClick={() => handleSubmit(assignment.id)}
              style={{ marginTop: "10px" }}
            >
              Upload Assignment
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default AssignmentsStudent;
